import math,json,sys
sand=[(20.79,8.96,30.09,15.03),(10.76,18.92,18.13,25.54)]
S={'bedrock':0.025,'sand':0.325}
def terr(x,y):
    return 'sand' if any(a<=x<=c and b<=y<=d for a,b,c,d in sand) else 'bedrock'
def sim(p,h,M):
    x,y=p;r=math.radians(h);w=0
    while w<M-1e-9:
        s=min(0.1,M-w);sl=S[terr(x,y)]
        x+=s*(1-sl)*math.cos(r);y+=s*(1-sl)*math.sin(r);w+=s
    return (x,y)
def wheel(p,q):
    # wheel metres to reach q from p
    h=math.degrees(math.atan2(q[1]-p[1],q[0]-p[0]))
    d=math.dist(p,q);x,y=p;w=0;r=math.radians(h);moved=0
    while moved<d-1e-9:
        sl=S[terr(x,y)];s=min(0.1*(1-sl),d-moved)
        x+=s*math.cos(r);y+=s*math.sin(r);moved+=s;w+=s/(1-sl)
    return h,w
def plan(p,q):
    out=[]
    while True:
        h,w=wheel(p,q)
        if w<1e-3: break
        m=min(5,w);out.append({"action":"drive","heading_deg":round(h,2),"metres":round(m,3)})
        p=sim(p,h,m)
        if m<5: break
    return out,p
if __name__=="__main__":
    a=json.loads(sys.argv[1]);
    if len(sys.argv)>2: S.update(json.loads(sys.argv[2]))
    print(json.dumps(plan(tuple(a[0]),tuple(a[1]))))
EOF
